// run with: bare lib/node_modules/disk-loader/disk-loader.test.js (needs bare 1.32+)
const Corestore = require('corestore')
const fs = require('bare-fs')
const os = require('bare-os')
const path = require('bare-path')
const b4a = require('b4a')
const autodisk = require('autodisk')
const disk_loader = require('./')

let failed = 0
module.exports = () => main().then(done) // the test of a module that uses this one runs it too
if (require.main === module) module.exports()

async function main () {
  const drive = autodisk({ store: new Corestore(fs.mkdtempSync(path.join(os.tmpdir(), 'disk-loader-test-'))).namespace('app') })
  await drive.ready()
  // a small app: main.js requires a file next to it, a json file and one module from outside the drive
  await drive.put('/main.js', b4a.from("const greet = require('./lib/greet.js')\nconst { name } = require('./config.json')\nmodule.exports = greet(name) + ' ' + require('b4a').toString(require('b4a').from('v1'))"))
  await drive.put('/lib/greet.js', b4a.from("module.exports = name => 'hello ' + name"))
  await drive.put('/config.json', b4a.from('{ "name": "lupay" }'))
  check('runs an app made of several files straight from an autodisk', await disk_loader({ drive, file: '/main.js', builtins: { b4a } }) === 'hello lupay v1')
  // npm dependencies can live inside the drive under /node_modules
  await drive.put('/node_modules/shout/package.json', b4a.from('{ "name": "shout", "main": "lib/index.js" }'))
  await drive.put('/node_modules/shout/lib/index.js', b4a.from("module.exports = text => text.toUpperCase() + '!'"))
  await drive.put('/loud.js', b4a.from("module.exports = require('shout')('hi')"))
  check('finds packages in the drive /node_modules', await disk_loader({ drive, file: '/loud.js' }) === 'HI!')
  const length = await wait_for_signed(drive)
  await drive.put('/main.js', b4a.from("module.exports = 'v2'"))
  check('runs the new version after an update', await disk_loader({ drive, file: '/main.js', builtins: { b4a } }) === 'v2')
  const pinned = drive.base.view.drive.checkout(length)
  check('runs the old version from a checkout at the pinned length', await disk_loader({ drive: pinned, file: '/main.js', builtins: { b4a } }) === 'hello lupay v1')
  await pinned.close()
  await drive.put('/fs.js', b4a.from("module.exports = require('bare-fs')"))
  // bare-fs is neither in the drive nor in builtins, so its just not found
  check('refuses modules that are not in builtins', await fails(disk_loader({ drive, file: '/fs.js', builtins: { b4a } }), 'MODULE_NOT_FOUND'))
  await drive.put('/sneaky.js', b4a.from("import('bare-fs')\nmodule.exports = 1"))
  check('refuses dynamic import()', await fails(disk_loader({ drive, file: '/sneaky.js' }), 'SyntaxError'))
  check('refuses files that are not in the drive', await fails(disk_loader({ drive, file: '/nope.js' }), 'MODULE_NOT_FOUND'))
  // the whole drive is in memory before the code runs, so a computed name works too, also deep in sub folders
  await drive.put('/lib/deep/name.js', b4a.from("module.exports = 'deep'"))
  await drive.put('/computed.js', b4a.from("const name = './lib/' + 'deep/name.js'\nmodule.exports = require(name)"))
  check('runs a require with a computed name', await disk_loader({ drive, file: '/computed.js' }) === 'deep')
  await drive.put('/missing.js', b4a.from("module.exports = require('./nope.js')"))
  check('a required file thats not in the drive gives MODULE_NOT_FOUND', await fails(disk_loader({ drive, file: '/missing.js' }), 'MODULE_NOT_FOUND'))
  await drive.close()
}

/***************************************
HELPERS
***************************************/
function check (name, ok) {
  console.log(`${ok ? 'ok' : 'not ok'} ${name}`)
  if (!ok) failed++
}

function done () {
  console.log(failed ? `${failed} failed` : 'all good')
  if (failed) throw new Error('disk-loader tests failed')
}

function fails (promise, reason) { return promise.then(() => false, err => (err.code || err.name) === reason) }

// the signed core lags a bit behind the latest writes, wait until it caught up
async function wait_for_signed (drive) {
  const core = drive.base.view.drive.core
  while (core.signedLength < core.length) {
    await drive.base.update()
    await new Promise(resolve => setTimeout(resolve, 50))
  }
  return core.signedLength
}
